public class PipelineTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    public static void main(String[] args) {
        java.util.function.Function<String, String> shout = Pipeline.shout();
        check("shout() is not null", true, shout != null);
        if (shout != null) {
            check("shout hello", "HELLO!", shout.apply("hello"));
            check("shout mixed case", "JAVA ROCKS!", shout.apply("Java Rocks"));
            check("shout empty string", "!", shout.apply(""));
        }
        java.util.function.Function<String, Integer> lengthTimesTwo =
                Pipeline.compose((String s) -> s.length(), (Integer n) -> n * 2);
        check("compose is not null", true, lengthTimesTwo != null);
        if (lengthTimesTwo != null) {
            check("compose length then double", 8, lengthTimesTwo.apply("java"));
        }
        java.util.function.Function<String, String> tagged =
                Pipeline.compose((String s) -> s + "f", (String s) -> s + "g");
        if (tagged != null) {
            check("compose applies f before g", "-fg", tagged.apply("-"));
        }
        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

