public class Pipeline {

    public static java.util.function.Function<String, String> shout() {
        return s -> s.toUpperCase() + "!";
    }

    public static <T, R, S> java.util.function.Function<T, S> compose(
            java.util.function.Function<T, R> f, java.util.function.Function<R, S> g) {
        return t -> g.apply(f.apply(t));
    }
}
